INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Carrier immer ein physischer Netzwerkanbieter?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch logische Dienste meinen"}, {"text": "Ja", "correct": false, "because": "Nicht auf Hardware beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe übernimmt ein Carrier im Netzwerk?', 3, '[{"text": "Datenübertragung bereitstellen", "correct": true, "because": "Kernfunktion eines Carriers"}, {"text": "IP-Adressen verwalten", "correct": false, "because": "Eher Aufgabe von ISPs"}, {"text": "Firewall konfigurieren", "correct": false, "because": "Kundenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen einen Carrier aus?', 5, '[{"text": "Bereitstellung von Bandbreite", "correct": true, "because": "Grundlage für Konnektivität"}, {"text": "Netzwerk-Infrastruktur", "correct": true, "because": "Physische oder virtuelle Basis"}, {"text": "Software-Entwicklung", "correct": false, "because": "Nicht primär"}, {"text": "Endgeräte-Wartung", "correct": false, "because": "Kundenverantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Carrier arbeitet auf Schicht 1 und 2. b) Er ist für die Datenverschlüsselung zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ist End-to-End"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Carriers?', 4, '[{"text": "Verfügbarkeit", "correct": false, "because": "Kritisch für Zuverlässigkeit"}, {"text": "Latenz", "correct": false, "because": "Wichtig für Performance"}, {"text": "Betriebssystem des Servers", "correct": true, "because": "Carrier-unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Carrier auch drahtlose Verbindungen anbietet?', 2, '[{"text": "Ja", "correct": true, "because": "Mobilfunk ist ein Beispiel"}, {"text": "Nein", "correct": false, "because": "Nicht nur kabelgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie nutzt ein Carrier typischerweise?', 3, '[{"text": "Glasfaser", "correct": true, "because": "Hohe Bandbreite und Reichweite"}, {"text": "Bluetooth", "correct": false, "because": "Kurzreichweite"}, {"text": "NFC", "correct": false, "because": "Nicht für Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind bei einem Carrier entscheidend?', 5, '[{"text": "Service-Level-Agreements", "correct": true, "because": "Definiert Zuverlässigkeit"}, {"text": "Netzwerkkapazität", "correct": true, "because": "Sichert Datenfluss"}, {"text": "CPU-Leistung", "correct": false, "because": "Server-spezifisch"}, {"text": "Software-Lizenzen", "correct": false, "because": "Kundenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Carrier sind für die physische Übertragung zuständig. b) Sie konfigurieren auch Router. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Router sind Kundenseite"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht von einem Carrier?', 4, '[{"text": "Stabile Verbindung", "correct": false, "because": "Kernanforderung"}, {"text": "Hohe Verfügbarkeit", "correct": false, "because": "Essenziell für Betrieb"}, {"text": "Lokale Software-Updates", "correct": true, "because": "Nicht Carrier-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Arbeiten Carrier nur mit IPv4?', 2, '[{"text": "Nein", "correct": true, "because": "IPv6 wird auch unterstützt"}, {"text": "Ja", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dienste bietet ein Carrier an?', 4, '[{"text": "Internetzugang", "correct": true, "because": "Kernservice"}, {"text": "VPN-Verbindungen", "correct": true, "because": "Häufig angeboten"}, {"text": "Antivirus-Schutz", "correct": false, "because": "Software-Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Carrier die Datenrate allein bestimmt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Infrastruktur und Vertrag"}, {"text": "Ja", "correct": false, "because": "Kunde beeinflusst auch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Carrier?', 3, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Minimiert Ausfälle"}, {"text": "Niedrige Kosten", "correct": false, "because": "Qualität wichtiger"}, {"text": "Schnelle Installation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Carrier betreiben Backbone-Netzwerke. b) Sie sind für Endgeräte-Konfiguration zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Endgeräte sind Kundenseite"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein guter Carrier?', 5, '[{"text": "Hohe Verfügbarkeit", "correct": true, "because": "Weniger Ausfälle"}, {"text": "Skalierbare Bandbreite", "correct": true, "because": "Flexibilität"}, {"text": "Kostenlose Hardware", "correct": false, "because": "Nicht üblich"}, {"text": "Software-Entwicklung", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Carrier unwichtig?', 3, '[{"text": "Netzwerkstabilität", "correct": false, "because": "Kernmerkmal"}, {"text": "Bandbreitenmanagement", "correct": false, "because": "Wichtig für Leistung"}, {"text": "Lokale Backup-Strategie", "correct": true, "because": "Kundenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzen Carrier immer eigene Hardware?', 3, '[{"text": "Nein", "correct": true, "because": "Können auch gemietet sein"}, {"text": "Ja", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Carrier auch für kleine Firmen relevant ist?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbare Lösungen"}, {"text": "Nein", "correct": false, "because": "Nicht nur Großkunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Standard erfüllt ein Carrier typischerweise?', 4, '[{"text": "Ethernet", "correct": true, "because": "Grundlage moderner Netze"}, {"text": "USB", "correct": false, "because": "Geräte-spezifisch"}, {"text": "SATA", "correct": false, "because": "Speichertechnik"}]');
